repo.Setup(r => r.FindAsync(It.IsAny<Guid>(), It.IsAny<CancellationToken>()))
    .ReturnsAsync(new Order { Id = orderId, Total = 42m });

var email = new Mock<IEmailSender>();

var service = new OrderService(repo.Object, email.Object);

await service.ShipAsync(orderId);

// The interaction that must have happened
email.Verify(e => e.SendShippedAsync(orderId, It.IsAny<CancellationToken>()), Times.Once);

// The interaction that must not have happened
email.Verify(e => e.SendConfirmationAsync(It.IsAny<Guid>(), It.IsAny<CancellationToken>()), Times.Never);
